SELECT DATE_FORMAT(a.ENDDATE, '%Y-%m') AS `月份`, a.STOCKSNAME AS `股票名称`, a.STOCKCODE AS `股票代码`, ROUND(AVG(a.TVALUE) / 100000000, 2) AS `日均成交额(亿)` FROM ANA_STK_EXPR_IDX a JOIN GET_A_SEC_CODE b ON a.INNER_CODE = b.INNER_CODE WHERE b.SEC_SNAME LIKE '%格力电器%' AND a.ENDDATE >= '2026-08-01 00:00:00' AND a.ENDDATE <= '2026-08-31 23:59:59' AND a.TVALUE IS NOT NULL GROUP BY DATE_FORMAT(a.ENDDATE, '%Y-%m'), a.STOCKSNAME, a.STOCKCODE LIMIT 1;
